using ContosoUniversity.Data;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests;

/// <summary>
/// Shared helper for creating in-memory SchoolContext instances for tests.
/// Each call returns a fresh context with a unique database name to ensure test isolation.
/// </summary>
public static class TestHelper
{
    public static SchoolContext CreateContext(string dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        return new SchoolContext(options);
    }

    /// <summary>
    /// Creates a context sharing the same in-memory database as another context.
    /// Useful for simulating multiple reads against the same data store.
    /// </summary>
    public static SchoolContext CreateContext(DbContextOptions<SchoolContext> options)
    {
        return new SchoolContext(options);
    }

    public static DbContextOptions<SchoolContext> CreateOptions(string dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        return new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
    }
}

