using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests;

public class SchoolContextTests
{
    [Fact]
    public void Constructor_WithInMemoryOptions_CreatesContext()
    {
        // Arrange & Act
        using var context = TestHelper.CreateContext();

        // Assert
        Assert.NotNull(context);
        Assert.NotNull(context.Courses);
        Assert.NotNull(context.Students);
        Assert.NotNull(context.Instructors);
        Assert.NotNull(context.Departments);
        Assert.NotNull(context.Enrollments);
        Assert.NotNull(context.OfficeAssignments);
        Assert.NotNull(context.CourseAssignments);
        Assert.NotNull(context.People);
        Assert.NotNull(context.Notifications);
    }

    [Fact]
    public void Students_AddAndRetrieve_PersistsToDatabase()
    {
        // Arrange
        var dbName = Guid.NewGuid().ToString();
        using var context = TestHelper.CreateContext(dbName);
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Act
        context.Students.Add(student);
        context.SaveChanges();

        // Assert
        using var readContext = TestHelper.CreateContext(dbName);
        var retrieved = readContext.Students.Single();
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal("Student", retrieved.LastName);
        Assert.Equal(new DateTime(2023, 9, 1), retrieved.EnrollmentDate);
    }

    [Fact]
    public void Instructors_AddAndRetrieve_PersistsToDatabase()
    {
        // Arrange
        var dbName = Guid.NewGuid().ToString();
        using var context = TestHelper.CreateContext(dbName);
        var instructor = new Instructor
        {
            FirstMidName = "John",
            LastName = "Doe",
            HireDate = new DateTime(2020, 1, 15)
        };

        // Act
        context.Instructors.Add(instructor);
        context.SaveChanges();

        // Assert
        using var readContext = TestHelper.CreateContext(dbName);
        var retrieved = readContext.Instructors.Single();
        Assert.Equal("John", retrieved.FirstMidName);
        Assert.Equal("Doe", retrieved.LastName);
        Assert.Equal(new DateTime(2020, 1, 15), retrieved.HireDate);
    }

    [Fact]
    public void CourseAssignment_CompositeKey_WorksCorrectly()
    {
        // Arrange
        var dbName = Guid.NewGuid().ToString();
        using var context = TestHelper.CreateContext(dbName);

        var instructor = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "Smith",
            HireDate = DateTime.Now
        };
        context.Instructors.Add(instructor);

        var dept = new Department
        {
            Name = "Test Dept",
            Budget = 100000,
            StartDate = DateTime.Now
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 1001,
            Title = "Test Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var assignment = new CourseAssignment
        {
            CourseID = course.CourseID,
            InstructorID = instructor.ID
        };

        // Act
        context.CourseAssignments.Add(assignment);
        context.SaveChanges();

        // Assert
        using var readContext = TestHelper.CreateContext(dbName);
        var retrieved = readContext.CourseAssignments.Single();
        Assert.Equal(course.CourseID, retrieved.CourseID);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
    }

    [Fact]
    public void OfficeAssignment_OneToOneWithInstructor_WorksCorrectly()
    {
        // Arrange
        var dbName = Guid.NewGuid().ToString();
        using var context = TestHelper.CreateContext(dbName);

        var instructor = new Instructor
        {
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var office = new OfficeAssignment
        {
            InstructorID = instructor.ID,
            Location = "Smith 17"
        };
        context.OfficeAssignments.Add(office);
        context.SaveChanges();

        // Assert
        using var readContext = TestHelper.CreateContext(dbName);
        var retrieved = readContext.OfficeAssignments
            .Include(o => o.Instructor)
            .Single();
        Assert.Equal("Smith 17", retrieved.Location);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
    }

    [Fact]
    public void TPH_Inheritance_StudentAndInstructorSharePersonTable()
    {
        // Arrange
        var dbName = Guid.NewGuid().ToString();
        using var context = TestHelper.CreateContext(dbName);

        context.Students.Add(new Student
        {
            FirstMidName = "Alice",
            LastName = "Wonder",
            EnrollmentDate = DateTime.Now
        });
        context.Instructors.Add(new Instructor
        {
            FirstMidName = "Bob",
            LastName = "Builder",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>()
        });
        context.SaveChanges();

        // Act
        using var readContext = TestHelper.CreateContext(dbName);
        var people = readContext.People.ToList();
        var students = readContext.Students.ToList();
        var instructors = readContext.Instructors.ToList();

        // Assert
        Assert.Equal(2, people.Count);
        Assert.Single(students);
        Assert.Single(instructors);
        Assert.Equal("Alice", students[0].FirstMidName);
        Assert.Equal("Bob", instructors[0].FirstMidName);
    }

    [Fact]
    public void Enrollment_Relationship_LinksStudentAndCourse()
    {
        // Arrange
        var dbName = Guid.NewGuid().ToString();
        using var context = TestHelper.CreateContext(dbName);

        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = DateTime.Now
        };
        context.Students.Add(student);

        var dept = new Department { Name = "Dept", Budget = 50000, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 2001,
            Title = "TestCourse",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var enrollment = new Enrollment
        {
            StudentID = student.ID,
            CourseID = course.CourseID,
            Grade = Grade.A
        };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        // Assert
        using var readContext = TestHelper.CreateContext(dbName);
        var retrieved = readContext.Enrollments
            .Include(e => e.Student)
            .Include(e => e.Course)
            .Single();
        Assert.Equal(student.ID, retrieved.StudentID);
        Assert.Equal(course.CourseID, retrieved.CourseID);
        Assert.Equal(Grade.A, retrieved.Grade);
    }
}

