using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests;

public class DbInitializerTests
{
    [Fact]
    public void Initialize_EmptyDatabase_SeedsStudents()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(8, context.Students.Count());
        Assert.Contains(context.Students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
        Assert.Contains(context.Students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsInstructors()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(5, context.Instructors.Count());
        Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie");
        Assert.Contains(context.Instructors, i => i.LastName == "Zheng");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsDepartments()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(4, context.Departments.Count());
        Assert.Contains(context.Departments, d => d.Name == "English");
        Assert.Contains(context.Departments, d => d.Name == "Mathematics");
        Assert.Contains(context.Departments, d => d.Name == "Engineering");
        Assert.Contains(context.Departments, d => d.Name == "Economics");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourses()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(7, context.Courses.Count());
        Assert.Contains(context.Courses, c => c.Title == "Chemistry" && c.CourseID == 1050);
        Assert.Contains(context.Courses, c => c.Title == "Literature" && c.CourseID == 2042);
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(3, context.OfficeAssignments.Count());
        Assert.Contains(context.OfficeAssignments, o => o.Location == "Smith 17");
        Assert.Contains(context.OfficeAssignments, o => o.Location == "Gowan 27");
        Assert.Contains(context.OfficeAssignments, o => o.Location == "Thompson 304");
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourseAssignments()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(8, context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsEnrollments()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        Assert.Equal(11, context.Enrollments.Count());
        // Verify specific enrollment with grade
        var alexanderChemistry = context.Enrollments
            .Single(e => e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry");
        Assert.Equal(Grade.A, alexanderChemistry.Grade);
    }

    [Fact]
    public void Initialize_AlreadySeeded_DoesNotDuplicateData()
    {
        // Arrange
        using var context = TestHelper.CreateContext();
        DbInitializer.Initialize(context);
        var initialStudentCount = context.Students.Count();
        var initialCourseCount = context.Courses.Count();

        // Act — call Initialize again
        DbInitializer.Initialize(context);

        // Assert — counts should remain the same
        Assert.Equal(initialStudentCount, context.Students.Count());
        Assert.Equal(initialCourseCount, context.Courses.Count());
    }

    [Fact]
    public void Initialize_SeedsCorrectDepartmentBudgets()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        var english = context.Departments.Single(d => d.Name == "English");
        Assert.Equal(350000m, english.Budget);
        var math = context.Departments.Single(d => d.Name == "Mathematics");
        Assert.Equal(100000m, math.Budget);
    }

    [Fact]
    public void Initialize_LinksDepartmentToAdministrator()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        var english = context.Departments.Single(d => d.Name == "English");
        var admin = context.Instructors.Single(i => i.ID == english.InstructorID);
        Assert.Equal("Abercrombie", admin.LastName);
    }

    [Fact]
    public void Initialize_SeedsCourseCreditsCorrectly()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert
        var calculus = context.Courses.Single(c => c.Title == "Calculus");
        Assert.Equal(4, calculus.Credits);
        var chemistry = context.Courses.Single(c => c.Title == "Chemistry");
        Assert.Equal(3, chemistry.Credits);
    }

    [Fact]
    public void Initialize_EnrollmentWithNullGrade_IsPreserved()
    {
        // Arrange
        using var context = TestHelper.CreateContext();

        // Act
        DbInitializer.Initialize(context);

        // Assert — Anand's Chemistry enrollment has no grade
        var anandChemistry = context.Enrollments
            .Single(e => e.Student.LastName == "Anand" && e.Course.Title == "Chemistry");
        Assert.Null(anandChemistry.Grade);
    }
}

