using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestHelper.CreateContext();
        _controller = new StudentsController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Student CreateTestStudent(string firstName = "Test", string lastName = "Student", DateTime? enrollmentDate = null)
    {
        var student = new Student
        {
            FirstMidName = firstName,
            LastName = lastName,
            EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();
        return student;
    }

    // === Index Tests ===

    [Fact]
    public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
    {
        // Arrange
        CreateTestStudent("Alice", "Zulu");
        CreateTestStudent("Bob", "Alpha");

        // Act
        var result = _controller.Index(null, null, null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(2, model.Count);
        Assert.Equal("Alpha", model[0].LastName);
        Assert.Equal("Zulu", model[1].LastName);
    }

    [Fact]
    public void Index_NameDescSort_ReturnsDescendingOrder()
    {
        // Arrange
        CreateTestStudent("Alice", "Alpha");
        CreateTestStudent("Bob", "Zulu");

        // Act
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Zulu", model[0].LastName);
        Assert.Equal("Alpha", model[1].LastName);
    }

    [Fact]
    public void Index_DateSort_ReturnsOrderedByDateAscending()
    {
        // Arrange
        CreateTestStudent("Late", "Student", new DateTime(2024, 1, 1));
        CreateTestStudent("Early", "Person", new DateTime(2020, 1, 1));

        // Act
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Person", model[0].LastName);
        Assert.Equal("Student", model[1].LastName);
    }

    [Fact]
    public void Index_DateDescSort_ReturnsOrderedByDateDescending()
    {
        // Arrange
        CreateTestStudent("Late", "Student", new DateTime(2024, 1, 1));
        CreateTestStudent("Early", "Person", new DateTime(2020, 1, 1));

        // Act
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Student", model[0].LastName);
        Assert.Equal("Person", model[1].LastName);
    }

    [Fact]
    public void Index_SearchByLastName_FiltersCorrectly()
    {
        // Arrange
        CreateTestStudent("Alice", "Smith");
        CreateTestStudent("Bob", "Jones");

        // Act
        var result = _controller.Index(null, null, "Smith", null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Smith", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersCorrectly()
    {
        // Arrange
        CreateTestStudent("Alice", "Smith");
        CreateTestStudent("Bob", "Jones");

        // Act
        var result = _controller.Index(null, null, "Alice", null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Alice", model[0].FirstMidName);
    }

    [Fact]
    public void Index_SearchString_ResetsPageTo1()
    {
        // Arrange
        CreateTestStudent("Alice", "Smith");

        // Act
        var result = _controller.Index(null, null, "Smith", 3) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearchUsesCurrentFilter_PreservesFilter()
    {
        // Arrange
        CreateTestStudent("Alice", "Smith");
        CreateTestStudent("Bob", "Jones");

        // Act
        var result = _controller.Index(null, "Smith", null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Smith", model[0].LastName);
    }

