using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _envMock;
    private readonly ILogger<CoursesController> _logger;

    public CoursesControllerTests()
    {
        _context = TestHelper.CreateContext();
        _envMock = new Mock<IWebHostEnvironment>();
        _envMock.Setup(e => e.WebRootPath).Returns((string)null);
        _envMock.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _logger = NullLogger<CoursesController>.Instance;
        _controller = new CoursesController(_context, _envMock.Object, _logger);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department CreateTestDepartment(string name = "Test Dept")
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course CreateTestCourse(int courseId = 1001, string title = "Test Course", int credits = 3, Department dept = null)
    {
        if (dept == null) dept = CreateTestDepartment();
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    // === Index Tests ===

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        // Arrange
        var dept = CreateTestDepartment();
        CreateTestCourse(1001, "Course A", dept: dept);
        CreateTestCourse(1002, "Course B", dept: dept);

        // Act
        var result = _controller.Index() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_EmptyDatabase_ReturnsEmptyList()
    {
        // Act
        var result = _controller.Index() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Empty(model);
    }

    // === Details Tests ===

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        // Arrange
        var course = CreateTestCourse();

        // Act
        var result = _controller.Details(course.CourseID) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal("Test Course", model.Title);
        Assert.Equal(3, model.Credits);
    }

    // === Create GET Tests ===

    [Fact]
    public void Create_Get_ReturnsViewWithDepartmentSelectList()
    {
        // Arrange
        CreateTestDepartment("Engineering");

        // Act
        var result = _controller.Create() as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
        Assert.IsType<Course>(result.Model);
    }

    // === Create POST Tests ===

    [Fact]
    public void Create_Post_ValidCourse_NoImage_RedirectsToIndex()
    {
        // Arrange
        var dept = CreateTestDepartment();
        var course = new Course
        {
            CourseID = 2001,
            Title = "New Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        // Act
        var result = _controller.Create(course, null) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(1, _context.Courses.Count());
        var saved = _context.Courses.Single();
        Assert.Equal("New Course", saved.Title);
        Assert.Equal(3, saved.Credits);
    }

    [Fact]
    public void Create_Post_InvalidExtension_ReturnsViewWithError()
    {
        // Arrange
        var dept = CreateTestDepartment();
        var course = new Course
        {
            CourseID = 2001,
            Title = "Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.exe");
        fileMock.Setup(f => f.Length).Returns(1024);

        // Act
        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var error = _controller.ModelState["teachingMaterialImage"].Errors.First();
        Assert.Contains("valid image file", error.ErrorMessage);
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsViewWithError()
    {
        // Arrange
        var dept = CreateTestDepartment();
        var course = new Course
        {
