using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestHelper.CreateContext();
        _controller = new InstructorsController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Instructor CreateTestInstructor(string firstName = "John", string lastName = "Doe",
        DateTime? hireDate = null, List<CourseAssignment> assignments = null)
    {
        var instructor = new Instructor
        {
            FirstMidName = firstName,
            LastName = lastName,
            HireDate = hireDate ?? new DateTime(2020, 1, 1),
            CourseAssignments = assignments ?? new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department CreateTestDepartment(string name = "Test Dept")
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course CreateTestCourse(int courseId, string title = "Test Course", Department dept = null)
    {
        if (dept == null) dept = CreateTestDepartment();
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    // === Index Tests ===

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructors()
    {
        // Arrange
        CreateTestInstructor("Alice", "Alpha");
        CreateTestInstructor("Bob", "Beta");

        // Act
        var result = _controller.Index(null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulateCourses()
    {
        // Arrange
        var dept = CreateTestDepartment();
        var course = CreateTestCourse(5001, "Algebra", dept);
        var instructor = CreateTestInstructor("Alice", "Alpha");
        _context.CourseAssignments.Add(new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        });
        _context.SaveChanges();

        // Act
        var result = _controller.Index(instructor.ID, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
        Assert.Equal("Algebra", model.Courses.First().Title);
    }

    [Fact]
    public void Index_InstructorsOrderedByLastName()
    {
        // Arrange
        CreateTestInstructor("Charlie", "Zulu");
        CreateTestInstructor("Alice", "Alpha");

        // Act
        var result = _controller.Index(null, null) as ViewResult;

        // Assert
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        var instructors = model.Instructors.ToList();
        Assert.Equal("Alpha", instructors[0].LastName);
        Assert.Equal("Zulu", instructors[1].LastName);
    }

    // === Details Tests ===

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        // Arrange
        var instructor = CreateTestInstructor("Alice", "Smith");

        // Act
        var result = _controller.Details(instructor.ID) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Alice", model.FirstMidName);
        Assert.Equal("Smith", model.LastName);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Details(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    // === Create GET Tests ===

    [Fact]
    public void Create_Get_ReturnsViewWithCourseData()
    {
        // Arrange
        var dept = CreateTestDepartment();
        CreateTestCourse(6001, "Course1", dept);

        // Act
        var result = _controller.Create() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.Empty(model.CourseAssignments);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    // === Create POST Tests ===

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        // Arrange
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Instructor",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        var result = _controller.Create(instructor, null) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(1, _context.Instructors.Count());
        var saved = _context.Instructors.Single();
        Assert.Equal("New", saved.FirstMidName);
        Assert.Equal("Instructor", saved.LastName);
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
    {
        // Arrange
        var dept = CreateTestDepartment();
        var course1 = CreateTestCourse(7001, "Course A", dept);
        var course2 = CreateTestCourse(7002, "Course B", dept);
        var instructor = new Instructor
        {
            FirstMidName = "Multi",
            LastName = "Course",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        var result = _controller.Create(instructor, new[] { course1.CourseID.ToString(), course2.CourseID.ToString() }) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var saved = _context.Instructors.Include(i => i.CourseAssignments).Single();
        Assert.Equal(2, saved.CourseAssignments.Count);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        // Arrange
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        var result = _controller.Create(instructor, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
    }

    // === Edit GET Tests ===

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Edit(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithInstructor()
    {
        // Arrange
        var instructor = CreateTestInstructor("Alice", "Smith");

        // Act
        var result = _controller.Edit(instructor.ID) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Alice", model.FirstMidName);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    // === Delete GET Tests ===

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Delete(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithInstructor()
    {
        // Arrange
        var instructor = CreateTestInstructor("Alice", "Smith");

        // Act
        var result = _controller.Delete(instructor.ID) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Alice", model.FirstMidName);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Delete(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    // === DeleteConfirmed Tests ===

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesInstructor()
    {
        // Arrange
        var instructor = CreateTestInstructor("Alice", "Smith");

        // Act
        var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(0, _context.Instructors.Count());
    }

    [Fact]
    public void DeleteConfirmed_InstructorAdminOfDepartment_NullsDepartmentInstructorId()
    {
        // Arrange
        var instructor = CreateTestInstructor("Alice", "Smith");
        var dept = new Department
        {
            Name = "Test",
            Budget = 100000,
            StartDate = DateTime.Now,
            InstructorID = instructor.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        // Act
        var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.Null(updatedDept.InstructorID);
    }

    // === UpdateInstructorCourses Tests (indirect via private method) ===
    // We test UpdateInstructorCourses behavior through the full Edit flow indirectly,
    // but here we test the delete confirmed with course assignments scenario.

    [Fact]
    public void DeleteConfirmed_InstructorWithOfficeAssignment_RemovesBoth()
    {
        // Arrange
        var instructor = CreateTestInstructor("Alice", "Smith");
        _context.OfficeAssignments.Add(new OfficeAssignment
        {
            InstructorID = instructor.ID,
            Location = "Room 101"
        });
        _context.SaveChanges();

        // Act
        var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(0, _context.Instructors.Count());
    }
}

