using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests;

[Collection("NotificationServiceTests")]
public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestHelper.CreateContext();
        _controller = new NotificationsController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
        // Drain any leftover notifications
        DrainNotificationQueue();
    }

    public void Dispose()
    {
        DrainNotificationQueue();
        _controller.Dispose();
        _context.Dispose();
    }

    private void DrainNotificationQueue()
    {
        // Access the notification service through the controller's protected field
        // by using reflection or indirectly via GetNotifications
        // We'll just call GetNotifications to drain
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        svc.Dispose();
    }

    // === GetNotifications Tests ===

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        // Act
        var result = _controller.GetNotifications();

        // Assert
        Assert.NotNull(result);
        var jsonResult = Assert.IsType<JsonResult>(result);
        Assert.NotNull(jsonResult.Value);

        // Verify structure via dynamic
        var value = jsonResult.Value;
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");
        Assert.True((bool)successProp.GetValue(value));
        Assert.Equal(0, (int)countProp.GetValue(value));
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotifications()
    {
        // Arrange — send notifications via a separate NotificationService (shares static queue)
        var svc = new NotificationService();
        svc.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "Admin");
        svc.SendNotification("Course", "2", "Test Course", EntityOperation.UPDATE, "Admin");

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value;
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");
        var notificationsProp = value.GetType().GetProperty("notifications");
        Assert.True((bool)successProp.GetValue(value));
        Assert.Equal(2, (int)countProp.GetValue(value));
        var notifications = (List<Notification>)notificationsProp.GetValue(value);
        Assert.Equal(2, notifications.Count);
        Assert.Equal("Student", notifications[0].EntityType);
        Assert.Equal("Course", notifications[1].EntityType);

        svc.Dispose();
    }

    [Fact]
    public void GetNotifications_LimitsTen_ReturnsMaxTenNotifications()
    {
        // Arrange — enqueue 15 notifications
        var svc = new NotificationService();
        for (int i = 0; i < 15; i++)
        {
            svc.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
        }

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value;
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(10, (int)countProp.GetValue(value));

        svc.Dispose();
    }

    // === MarkAsRead Tests ===

    [Fact]
    public void MarkAsRead_ValidId_ReturnsSuccess()
    {
        // Act
        var result = _controller.MarkAsRead(1);

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp.GetValue(value));
    }

    // === Index Tests ===

    [Fact]
    public void Index_ReturnsView()
    {
        // Act
        var result = _controller.Index() as ViewResult;

        // Assert
        Assert.NotNull(result);
    }
}

