using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests;

public class HomeControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly HomeController _controller;

    public HomeControllerTests()
    {
        _context = TestHelper.CreateContext();
        _controller = new HomeController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsView()
    {
        // Act
        var result = _controller.Index() as ViewResult;

        // Assert
        Assert.NotNull(result);
    }

    [Fact]
    public void About_NoStudents_ReturnsEmptyList()
    {
        // Act
        var result = _controller.About() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void About_WithStudents_ReturnsGroupedEnrollmentData()
    {
        // Arrange
        _context.Students.Add(new Student
        {
            FirstMidName = "Alice",
            LastName = "Smith",
            EnrollmentDate = new DateTime(2023, 9, 1)
        });
        _context.Students.Add(new Student
        {
            FirstMidName = "Bob",
            LastName = "Jones",
            EnrollmentDate = new DateTime(2023, 9, 1)
        });
        _context.Students.Add(new Student
        {
            FirstMidName = "Charlie",
            LastName = "Brown",
            EnrollmentDate = new DateTime(2022, 9, 1)
        });
        _context.SaveChanges();

        // Act
        var result = _controller.About() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
        Assert.Equal(2, model.Count);

        var group2023 = model.Single(g => g.EnrollmentDate == new DateTime(2023, 9, 1));
        Assert.Equal(2, group2023.StudentCount);

        var group2022 = model.Single(g => g.EnrollmentDate == new DateTime(2022, 9, 1));
        Assert.Equal(1, group2022.StudentCount);
    }

    [Fact]
    public void About_SingleStudent_ReturnsSingleGroup()
    {
        // Arrange
        _context.Students.Add(new Student
        {
            FirstMidName = "Only",
            LastName = "Student",
            EnrollmentDate = new DateTime(2024, 1, 15)
        });
        _context.SaveChanges();

        // Act
        var result = _controller.About() as ViewResult;

        // Assert
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
        Assert.Single(model);
        Assert.Equal(new DateTime(2024, 1, 15), model[0].EnrollmentDate);
        Assert.Equal(1, model[0].StudentCount);
    }

    [Fact]
    public void Contact_SetsViewBagMessage()
    {
        // Act
        var result = _controller.Contact() as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("Your contact page.", _controller.ViewBag.Message);
    }

    [Fact]
    public void Error_ReturnsView()
    {
        // Act
        var result = _controller.Error() as ViewResult;

        // Assert
        Assert.NotNull(result);
    }

    [Fact]
    public void Unauthorized_SetsViewBagMessageAndReturnsView()
    {
        // Act
        var result = _controller.Unauthorized() as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal("You don't have permission to access this resource.", _controller.ViewBag.Message);
    }
}

