using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests;

public class ModelTests
{
    // === Person / FullName Tests ===

    [Fact]
    public void Person_FullName_ReturnsLastNameCommaFirstName()
    {
        // Arrange
        var student = new Student
        {
            FirstMidName = "Carson",
            LastName = "Alexander",
            EnrollmentDate = DateTime.Now
        };

        // Act
        var fullName = student.FullName;

        // Assert
        Assert.Equal("Alexander, Carson", fullName);
    }

    [Fact]
    public void Instructor_FullName_ReturnsLastNameCommaFirstName()
    {
        // Arrange
        var instructor = new Instructor
        {
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = DateTime.Now
        };

        // Act & Assert
        Assert.Equal("Abercrombie, Kim", instructor.FullName);
    }

    // === ErrorViewModel Tests ===

    [Fact]
    public void ErrorViewModel_ShowRequestId_TrueWhenRequestIdSet()
    {
        // Arrange
        var model = new ErrorViewModel { RequestId = "abc123" };

        // Act & Assert
        Assert.True(model.ShowRequestId);
    }

    [Fact]
    public void ErrorViewModel_ShowRequestId_FalseWhenRequestIdNull()
    {
        // Arrange
        var model = new ErrorViewModel { RequestId = null };

        // Act & Assert
        Assert.False(model.ShowRequestId);
    }

    [Fact]
    public void ErrorViewModel_ShowRequestId_FalseWhenRequestIdEmpty()
    {
        // Arrange
        var model = new ErrorViewModel { RequestId = "" };

        // Act & Assert
        Assert.False(model.ShowRequestId);
    }

    // === Course Tests ===

    [Fact]
    public void Course_Properties_SetAndGet()
    {
        // Arrange & Act
        var course = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1,
            TeachingMaterialImagePath = "/images/chem.jpg"
        };

        // Assert
        Assert.Equal(1050, course.CourseID);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
        Assert.Equal(1, course.DepartmentID);
        Assert.Equal("/images/chem.jpg", course.TeachingMaterialImagePath);
    }

    // === Enrollment Tests ===

    [Fact]
    public void Enrollment_Grade_CanBeNull()
    {
        // Arrange
        var enrollment = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 100,
            StudentID = 1,
            Grade = null
        };

        // Assert
        Assert.Null(enrollment.Grade);
    }

    [Fact]
    public void Enrollment_Grade_AllValuesValid()
    {
        // Assert
        Assert.Equal(0, (int)Grade.A);
        Assert.Equal(1, (int)Grade.B);
        Assert.Equal(2, (int)Grade.C);
        Assert.Equal(3, (int)Grade.D);
        Assert.Equal(4, (int)Grade.F);
    }

    // === Department Tests ===

    [Fact]
    public void Department_Properties_SetAndGet()
    {
        // Arrange & Act
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 350000,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = 5
        };

        // Assert
        Assert.Equal(1, dept.DepartmentID);
        Assert.Equal("Engineering", dept.Name);
        Assert.Equal(350000m, dept.Budget);
        Assert.Equal(new DateTime(2007, 9, 1), dept.StartDate);
        Assert.Equal(5, dept.InstructorID);
    }

    [Fact]
    public void Department_InstructorID_CanBeNull()
    {
        // Arrange
        var dept = new Department { InstructorID = null };

        // Assert
        Assert.Null(dept.InstructorID);
    }

    // === Notification Tests ===

    [Fact]
    public void Notification_Properties_SetAndGet()
    {
        // Arrange & Act
        var notification = new Notification
        {
            Id = 1,
            EntityType = "Student",
            EntityId = "42",
            Operation = "CREATE",
            Message = "Test message",
            CreatedAt = new DateTime(2024, 1, 1, 12, 0, 0),
            CreatedBy = "Admin",
            IsRead = false,
            ReadAt = null
        };

        // Assert
        Assert.Equal(1, notification.Id);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("Test message", notification.Message);
        Assert.Equal(new DateTime(2024, 1, 1, 12, 0, 0), notification.CreatedAt);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.Null(notification.ReadAt);
    }

    [Fact]
    public void Notification_ReadAt_CanBeSet()
    {
        // Arrange
        var readTime = new DateTime(2024, 1, 2, 10, 0, 0);
        var notification = new Notification
        {
            IsRead = true,
            ReadAt = readTime
        };

        // Assert
        Assert.True(notification.IsRead);
        Assert.Equal(readTime, notification.ReadAt);
    }

    // === EntityOperation Enum Tests ===

    [Fact]
    public void EntityOperation_HasExpectedValues()
    {
        Assert.Equal(0, (int)EntityOperation.CREATE);
        Assert.Equal(1, (int)EntityOperation.UPDATE);
        Assert.Equal(2, (int)EntityOperation.DELETE);
    }

    // === OfficeAssignment Tests ===

    [Fact]
    public void OfficeAssignment_Properties_SetAndGet()
    {
        var oa = new OfficeAssignment
        {
            InstructorID = 5,
            Location = "Smith 17"
        };

        Assert.Equal(5, oa.InstructorID);
        Assert.Equal("Smith 17", oa.Location);
    }

    // === CourseAssignment Tests ===

    [Fact]
    public void CourseAssignment_Properties_SetAndGet()
    {
        var ca = new CourseAssignment
        {
            InstructorID = 3,
            CourseID = 1050
        };

        Assert.Equal(3, ca.InstructorID);
        Assert.Equal(1050, ca.CourseID);
    }

    // === ViewModel Tests ===

    [Fact]
    public void AssignedCourseData_Properties_SetAndGet()
    {
        var data = new ContosoUniversity.Models.SchoolViewModels.AssignedCourseData
        {
            CourseID = 100,
            Title = "Test",
            Assigned = true
        };

