9. namespace ContosoUniversity.Tests;
10. 
11. [Collection("NotificationServiceTests")]
12. public class NotificationsControllerTests : IDisposable
13. {
14.     private readonly SchoolContext _context;
15.     private readonly NotificationsController _controller;
16. 
17.     public NotificationsControllerTests()
18.     {
19.         _context = TestHelper.CreateContext();
20.         _controller = new NotificationsController(_context);
21.         _controller.ControllerContext = new ControllerContext
22.         {
23.             HttpContext = new DefaultHttpContext()
24.         };
25.         // Drain any leftover notifications
26.         DrainNotificationQueue();
27.     }
28. 
29.     public void Dispose()
30.     {
31.         DrainNotificationQueue();
32.         _controller.Dispose();
33.         _context.Dispose();
34.     }
35. 
36.     private void DrainNotificationQueue()
37.     {
38.         // Access the notification service through the controller's protected field
39.         // by using reflection or indirectly via GetNotifications
40.         // We'll just call GetNotifications to drain
41.         var svc = new NotificationService();
42.         while (svc.ReceiveNotification() != null) { }
43.         svc.Dispose();
44.     }
45. 
46.     // === GetNotifications Tests ===
47. 
48.     [Fact]
49.     public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
50.     {
51.         // Act
52.         var result = _controller.GetNotifications();
53. 
54.         // Assert
55.         Assert.NotNull(result);
56.         var jsonResult = Assert.IsType<JsonResult>(result);
57.         Assert.NotNull(jsonResult.Value);
58. 
59.         // Verify structure via dynamic
60.         var value = jsonResult.Value;
61.         var successProp = value.GetType().GetProperty("success");
62.         var countProp = value.GetType().GetProperty("count");
63.         Assert.True((bool)successProp.GetValue(value));
64.         Assert.Equal(0, (int)countProp.GetValue(value));
65.     }
66. 
67.     [Fact]
68.     public void GetNotifications_WithNotifications_ReturnsNotifications()
69.     {
70.         // Arrange — send notifications via a separate NotificationService (shares static queue)
71.         var svc = new NotificationService();
72.         svc.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "Admin");
73.         svc.SendNotification("Course", "2", "Test Course", EntityOperation.UPDATE, "Admin");
74. 
75.         // Act
76.         var result = _controller.GetNotifications();
77. 
78.         // Assert
79.         var jsonResult = Assert.IsType<JsonResult>(result);
80.         var value = jsonResult.Value;
81.         var successProp = value.GetType().GetProperty("success");
82.         var countProp = value.GetType().GetProperty("count");
83.         var notificationsProp = value.GetType().GetProperty("notifications");
84.         Assert.True((bool)successProp.GetValue(value));
85.         Assert.Equal(2, (int)countProp.GetValue(value));
