 namespace ContosoUniversity.Tests;

 [Collection("NotificationServiceTests")]
 public class NotificationsControllerTests : IDisposable
 {
     private readonly SchoolContext _context;
     private readonly NotificationsController _controller;

     public NotificationsControllerTests()
     {
         _context = TestHelper.CreateContext();
         _controller = new NotificationsController(_context);
         _controller.ControllerContext = new ControllerContext
         {
             HttpContext = new DefaultHttpContext()
         };
         // Drain any leftover notifications
         DrainNotificationQueue();
     }

     public void Dispose()
     {
         DrainNotificationQueue();
         _controller.Dispose();
         _context.Dispose();
     }

     private void DrainNotificationQueue()
     {
         // Access the notification service through the controller's protected field
         // by using reflection or indirectly via GetNotifications
         // We'll just call GetNotifications to drain
         var svc = new NotificationService();
         while (svc.ReceiveNotification() != null) { }
         svc.Dispose();
     }

