+    // === PaginatedList boundary/edge tests ===
+
+    [Fact]
+    public void PaginatedList_HasNextPage_WhenPageIndexEqualsTotalPages_ReturnsFalse()
+    {
+        // This catches the mutation: changing < to <= in HasNextPage
+        var source = Enumerable.Range(1, 10).AsQueryable();
+        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);
+
+        // PageIndex=1, TotalPages=1 => HasNextPage should be false
+        Assert.Equal(1, result.PageIndex);
+        Assert.Equal(1, result.TotalPages);
+        Assert.False(result.HasNextPage);
+    }
+
+    [Fact]
+    public void PaginatedList_HasPreviousPage_WhenPageIndexEquals1_ReturnsFalse()
+    {
+        // Catches mutation: changing > to >= in HasPreviousPage
+        var source = Enumerable.Range(1, 20).AsQueryable();
+        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);
+
+        Assert.Equal(1, result.PageIndex);
+        Assert.False(result.HasPreviousPage);
+    }
+
+    [Fact]
+    public void PaginatedList_TotalPages_CeilingBehavior_19ItemsPageSize10_Returns2()
+    {
+        // Catches mutation: Math.Ceiling to Math.Floor
+        var source = Enumerable.Range(1, 19).AsQueryable();
+        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);
+
+        Assert.Equal(2, result.TotalPages);
+    }
+
+    [Fact]
+    public void PaginatedList_TotalPages_11Items_Returns2NotFloor1()
+    {
+        // Directly catches Math.Ceiling replaced with (int)(count/pageSize)
+        var source = Enumerable.Range(1, 11).AsQueryable();
+        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);
+
+        Assert.Equal(2, result.TotalPages);
+        Assert.True(result.HasNextPage);
+    }
+
+    // === StudentsController search OR logic test ===
