+        using var context = TestHelper.CreateContext();
+        context.Students.Add(new Student { FirstMidName = "UniqueFirst", LastName = "CommonLast", EnrollmentDate = DateTime.Now });
+        context.Students.Add(new Student { FirstMidName = "OtherName", LastName = "DifferentLast", EnrollmentDate = DateTime.Now });
+        context.SaveChanges();
+
+        var controller = new StudentsController(context);
+        controller.ControllerContext = new ControllerContext { HttpContext = new DefaultHttpContext() };
+
+        // Search by first name only — should match even though last name doesn't contain search string
+        var result = controller.Index(null, null, "UniqueFirst", null) as ViewResult;
+
+        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
+        Assert.Single(model);
+        Assert.Equal("UniqueFirst", model[0].FirstMidName);
