+    [Fact]
+    public void NotificationService_CreateMessage_ContainsNewPrefix()
+    {
+        // Verify CREATE message starts with "New" — catches swapped case labels
+        var svc = new ContosoUniversity.Services.NotificationService();
+        // Drain
+        while (svc.ReceiveNotification() != null) { }
+
+        svc.SendNotification("Student", "1", "Alice", EntityOperation.CREATE);
+        var n = svc.ReceiveNotification();
+
+        Assert.NotNull(n);
+        Assert.StartsWith("New", n.Message);
+        Assert.Contains("created", n.Message);
+        Assert.DoesNotContain("updated", n.Message);
+        Assert.DoesNotContain("deleted", n.Message);
